const input = $input.first().json;
const body = (typeof input.body === 'object' && input.body !== null) ? input.body : input;

function escapeHtml(value) {
  return String(value || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

// El sandbox de Code node de esta instancia de n8n no expone el global URL
// (igual que no expone crypto). Validacion por expresion regular, sin globals.
const HTTP_URL_RE = /^https?:\/\/[^\s/$.?#][^\s]*$/i;
function requireUrl(value, label) {
  const raw = String(value || '').trim();
  if (!HTTP_URL_RE.test(raw)) throw new Error('Falta ' + label + ' valido (debe ser una URL http/https)');
  return raw;
}
function optionalUrl(value) {
  const raw = String(value || '').trim();
  return HTTP_URL_RE.test(raw) ? raw : '';
}

const event = String(body.event || (body.password_setup_url ? 'setup_completed' : 'setup_required')).trim();
const nombre = String(body.nombre || body.dealer_name || '').trim();
const email = String(body.email || '').trim();
if (nombre.length < 2) throw new Error('Falta nombre del fundador');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) throw new Error('Email invalido');

const prospectoId = String(body.prospecto_id || '');
const telefono = String(body.telefono || body.phone || '').trim();
const whatsapp = String(body.whatsapp || '').trim();
const dealerSlug = String(body.dealer_slug || '').trim();
const loginUrl = optionalUrl(body.login_url) || 'https://blacklabelmarket.es/login';
const dashboardUrl = optionalUrl(body.dashboard_url) || 'https://blacklabelmarket.es/dashboard';
const adminUrl = optionalUrl(body.admin_url) || 'https://blacklabelmarket.es/admin/dealers';
const setupContext = body.setup_context || {};

const safeNombre = escapeHtml(nombre);
const safeEmail = escapeHtml(email);
const limite = new Date(Date.now() + (event === 'setup_completed' ? 2 : 7) * 86400000);
const fechaLimite = limite.toISOString().slice(0, 10);

const legalFooter = '<div style="margin-top:24px;padding-top:14px;border-top:1px solid #ddd;font-size:11px;color:#777;line-height:1.5">' +
  'Black Label Market es una marca de <strong>KAZAWEB, S.L.U.</strong> (NIF B42761254), con domicilio en Lugar Rebordelo nº 35, Planta 2, 15930 Boiro, A Coruña. Inscrita en el Registro Mercantil de Santiago de Compostela, Tomo 395, Folio 51, Hoja SC-51053.<br>' +
  'Puedes solicitar la baja de comunicaciones o ejercer tus derechos de privacidad escribiendo a <a href="mailto:privacidad@blacklabelmarket.es">privacidad@blacklabelmarket.es</a>. Consulta nuestra <a href="https://blacklabelmarket.es/legal/privacidad">Política de Privacidad</a>.' +
  '</div>';

let emailSubject, emailHtml, taskTitle, taskType, taskEvidence;

if (event === 'setup_completed') {
  const passwordSetupUrl = requireUrl(body.password_setup_url || body.passwordSetupUrl, 'password_setup_url');
  const safePasswordUrl = escapeHtml(passwordSetupUrl);
  const safeDashboardUrl = escapeHtml(dashboardUrl);
  emailSubject = 'Black Label Market — crea tu contraseña de acceso';
  emailHtml = '<p>Buenas ' + safeNombre + ',</p>' +
    '<p>Hemos recibido la configuración de vuestro showroom. Antes de nada, os toca un único paso: crear la contraseña de vuestra cuenta para poder entrar al panel.</p>' +
    '<div style="margin:18px 0;padding:16px;border:1px solid #C6A64B;background:#f6f4ee">' +
    '<p style="margin-top:0"><strong>Vuestro acceso:</strong></p>' +
    '<p>Usuario: ' + safeEmail + '</p>' +
    '<p><a href="' + safePasswordUrl + '" style="display:inline-block;padding:10px 14px;background:#111;color:#fff;text-decoration:none">Crear contraseña y entrar</a></p>' +
    '<p style="margin-bottom:0;font-size:13px;color:#555">Enlace de un solo uso. Si caduca antes de usarlo, pedid uno nuevo desde <a href="' + escapeHtml(loginUrl) + '">' + escapeHtml(loginUrl) + '</a>.</p>' +
    '</div>' +
    '<p>Ya podéis entrar al panel para consultar contactos, citas y el estado del inventario en <a href="' + safeDashboardUrl + '">' + safeDashboardUrl + '</a>. La página pública, en cambio, todavía no es visible: el equipo va a revisar antes el perfil, el logo y las fotos, y os avisaremos si hace falta ajustar algo antes de abrirla.</p>' +
    '<p>Un saludo,<br>Black Label Market</p>' +
    legalFooter;
  taskTitle = 'Configuración completada, revisar contenido - ' + nombre;
  taskType = 'Revisión contenido';
  taskEvidence = 'Setup completado desde sala tokenizada. Revisar perfil, logo, fotos, documento libre, contexto del asistente y stock. Admin: ' + adminUrl;
} else if (event === 'profile_published') {
  const publicUrl = requireUrl(body.public_url || body.publicUrl, 'public_url');
  const safePublicUrl = escapeHtml(publicUrl);
  emailSubject = 'Black Label Market — vuestro perfil ya está publicado';
  emailHtml = '<p>Buenas ' + safeNombre + ',</p>' +
    '<p>Ya está: vuestro perfil ha pasado la revisión editorial y está publicado en Black Label Market.</p>' +
    '<div style="margin:18px 0;padding:16px;border:1px solid #C6A64B;background:#f6f4ee">' +
    '<p style="margin-top:0"><strong>Vuestra ficha pública:</strong></p>' +
    '<p><a href="' + safePublicUrl + '" style="display:inline-block;padding:10px 14px;background:#111;color:#fff;text-decoration:none">Ver ficha pública</a></p>' +
    '</div>' +
    '<p>A partir de ahora, los compradores ya pueden encontraros y contactar directamente. Seguid gestionando vuestro inventario y las oportunidades que lleguen desde el panel.</p>' +
    '<p>Un saludo,<br>Black Label Market</p>' +
    legalFooter;
  taskTitle = 'Perfil publicado - ' + nombre;
  taskType = 'Aviso';
  taskEvidence = 'Perfil publicado por el equipo tras revisión editorial. Aviso enviado al showroom con enlace a su ficha publica.';
} else {
  const setupUrl = requireUrl(body.setup_url || body.setupRoomUrl, 'setup_url');
  const safeSetupUrl = escapeHtml(setupUrl);
  emailSubject = 'Black Label Market — preparar vuestro showroom fundador';
  emailHtml = '<p>Buenas ' + safeNombre + ',</p>' +
    '<p>Vuestra alta como showroom fundador está aprobada. Antes de dar acceso al panel vamos a preparar la presencia pública con el material correcto.</p>' +
    '<div style="margin:18px 0;padding:16px;border:1px solid #C6A64B;background:#f6f4ee">' +
    '<p style="margin-top:0"><strong>Sala privada de configuración:</strong></p>' +
    '<p><a href="' + safeSetupUrl + '" style="display:inline-block;padding:10px 14px;background:#111;color:#fff;text-decoration:none">Completar configuración</a></p>' +
    '<p style="margin-bottom:0;font-size:13px;color:#555">El enlace es privado y estará disponible durante 14 días.</p>' +
    '</div>' +
    '<p>Encontraréis el perfil pre-rellenado con los datos investigados antes de la visita: nombre, descripción, dirección, redes, especialidades y servicios. Confirmad lo correcto y corregid lo que falte.</p>' +
    '<p>También podéis indicar cómo preferís entregarnos el stock inicial: URL de feed o portal, CSV compatible con nuestra plantilla, o fotos y archivos sueltos para que lo preparemos nosotros.</p>' +
    '<p>Cuando enviéis la configuración generaremos un enlace de acceso nuevo. La página pública no se abrirá hasta que el equipo revise logo, fotos y primera unidad.</p>' +
    '<p>Un saludo,<br>Black Label Market</p>' +
    legalFooter;
  taskTitle = 'Acompañar configuración fundador - ' + nombre;
  taskType = 'Onboarding fundador';
  taskEvidence = 'WF-P3 envió sala tokenizada de configuración. No se han enviado credenciales todavía.';
}

return [{ json: { event, prospectoId, nombre, email, telefono, whatsapp, dealerSlug, fechaLimite, emailSubject, emailHtml, taskTitle, taskType, taskEvidence, adminUrl, setupContext } }];

const resp = $input.first().json || {};
const yaActivos = Array.isArray(resp.records) ? resp.records.length : 0;
const prospectoId = $('Validar input').first().json.prospectoId;
const hoy = new Date().toISOString().slice(0, 10);
return [{ json: { prospectoId, siguientePlaza: yaActivos + 1, fechaHoy: hoy } }];
